package main

import (
	"encoding/json"
	"os"
	"strconv"
	"testing"
)

// The BIP34 height cases shared with the web's parser (web/utils/coinbaseParser.ts heightFromCoinbase1):
// testdata/coinbase-height-vectors.json at the repo root, generated by testdata/gen_coinbase_height_vectors.py.
// parseBIP34Height writes templates.height, so every case's `height` is this function's answer (null = not parsed,
// stored as 0). A missing or empty file fails: the cases must never stop running silently.
type heightVector struct {
	Name      string  `json:"name"`
	Coinbase1 string  `json:"coinbase1"`
	Height    *string `json:"height"`
}

func TestSharedCoinbaseHeightVectors(t *testing.T) {
	raw, err := os.ReadFile("../testdata/coinbase-height-vectors.json")
	if err != nil {
		t.Fatalf("shared height vectors: %v", err)
	}
	var doc struct {
		Version int            `json:"version"`
		Cases   []heightVector `json:"cases"`
	}
	if err := json.Unmarshal(raw, &doc); err != nil {
		t.Fatalf("shared height vectors: %v", err)
	}
	if doc.Version != 1 || len(doc.Cases) < 20 {
		t.Fatalf("shared height vectors: version %d, %d cases", doc.Version, len(doc.Cases))
	}
	heights, none := 0, 0
	for _, c := range doc.Cases {
		h, ok := parseBIP34Height(c.Coinbase1)
		switch {
		case c.Height == nil && ok:
			t.Errorf("%s: got height %d, want none", c.Name, h)
		case c.Height != nil && !ok:
			t.Errorf("%s: got no height, want %s", c.Name, *c.Height)
		case c.Height != nil && strconv.FormatInt(h, 10) != *c.Height:
			t.Errorf("%s: got height %d, want %s", c.Name, h, *c.Height)
		}
		if c.Height != nil {
			heights++
		} else {
			none++
		}
	}
	t.Logf("%d cases: %d with a height, %d without", len(doc.Cases), heights, none)
}
